<script setup lang="ts">
import { ref,onMounted } from 'vue'
import { api,post } from '../api'
import { state,notify } from '../store'
import Icon from '../components/Icon.vue'
const text=ref(''),goal=ref(state.user?.goal||'岗位入门'),busy=ref(false),error=ref(''),card=ref<any>(),history=ref<any[]>([])
const examples=[{name:'自动驾驶 · 目标框选',text:'为自动驾驶项目完成道路图像的汽车与行人目标检测标注，要求准确框选、区分遮挡和截断情况，交付标注文件与质量报告。'},{name:'工业质检 · 缺陷辨别',text:'为工厂金属表面质检项目培训数据标注师，区分裂纹和划痕，标注缺陷区域，统一疑难样本规则，并完成试标、批量质检和返修。'},{name:'智能客服 · 文本实体',text:'为智能客服整理脱敏工单，识别人名、地点和机构实体，并标注用户意图，完成实体边界审核和数据交付。'}]
onMounted(async()=>{try{history.value=await api('/tasks')}catch(e){error.value=(e as Error).message}})
async function convert(){busy.value=true;error.value='';try{card.value=await post('/tasks/convert',{text:text.value,goal:goal.value});history.value=[card.value,...history.value];notify('学习任务卡已生成并保存。')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function download(){const c=card.value;const output=`# ${c.name}\n\n${c.scenario}\n\n## 学习步骤\n\n${c.steps.map((s:any,i:number)=>`${i+1}. ${s.title}\n${s.description}\n产出：${s.output}`).join('\n\n')}\n\n## 知识与技能\n${c.knowledge.join('、')}\n\n## 操作要点\n${c.safety.join('\n')}\n\n${c.ai_generated?'AI 生成内容，需结合正式项目规范使用。':'基于岗位教学规则生成。'}`;const url=URL.createObjectURL(new Blob([output],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='智基-学习任务卡.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<template><div class="content-width tasks-page"><header class="section-heading"><div><span class="eyebrow">以岗定教 · 把真实任务带进课堂</span><h1>企业任务，变成学习的起点。</h1><p class="muted">描述一项数据标注工作，得到可以一步步完成的学习任务卡。</p></div></header><div class="task-builder-layout"><section class="task-input-panel"><h2><Icon name="BriefcaseBusiness" :size="23"/>先说说这份工作</h2><form @submit.prevent="convert"><label for="enterprise-task">企业工作任务</label><textarea id="enterprise-task" v-model="text" required minlength="10" maxlength="4000" rows="7" placeholder="例如：为自动驾驶项目标注道路图片中的行人和车辆，完成试标、质检与数据交付…"></textarea><span class="input-counter">{{text.length}} / 4000</span><label>试试一个典型场景</label><div class="task-examples"><button v-for="e in examples" :key="e.name" type="button" @click="text=e.text">{{e.name}}<Icon name="Plus" :size="15"/></button></div><label for="task-goal">这次学习的目标</label><select id="task-goal" v-model="goal"><option>岗位入门</option><option>课程补强</option><option>竞赛备战</option></select><button class="btn dark full" :disabled="busy||text.trim().length<10"><Icon :name="busy?'LoaderCircle':'Sparkles'" :class="{spin:busy}" :size="18"/>{{busy?'正在分析岗位任务…':'生成学习任务卡'}}</button><p class="task-input-note">任务将关联知识点、操作步骤与平台训练资源。</p></form><div v-if="error" class="error-message" role="alert">{{error}}</div><section v-if="history.length" class="task-history"><h3>已保存的任务</h3><button v-for="t in history.slice(0,6)" :key="t.id" @click="card=t"><Icon name="FileCheck2" :size="16"/><span>{{t.name}}</span><Icon name="ChevronRight" :size="15"/></button></section></section><section class="task-output" :class="{empty:!card}"><div v-if="busy" class="task-generating"><Icon name="LoaderCircle" :size="40" class="spin"/><h2>把岗位要求，拆成可学会的步骤。</h2><p>正在匹配能力、知识资料和训练资源…</p></div><template v-else-if="card"><div class="task-card-top"><span class="pill purple">{{card.ai_generated?'AI 生成内容':'规则生成任务卡'}}</span><button class="icon-button" @click="download" aria-label="下载学习任务卡"><Icon name="Download" :size="19"/></button></div><h2>{{card.name}}</h2><p class="task-scenario">{{card.scenario}}</p><div v-if="card.notice" class="model-notice">{{card.notice}}</div><div class="task-tags"><span class="pill">{{card.goal}}</span><span class="pill">{{card.ability_id}} 能力训练</span></div><template v-if="card.clarifications?.length"><h3>开始前，确认项目规则</h3><ul class="task-safety"><li v-for="item in card.clarifications" :key="item">{{item}}</li></ul></template><h3>一步一步，完成任务</h3><ol class="task-steps"><li v-for="(s,i) in card.steps" :key="i"><span>{{Number(i)+1}}</span><div><h4>{{s.title}}</h4><p>{{s.description}}</p><small><Icon name="CheckCheck" :size="14"/>产出：{{s.output}}</small></div></li></ol><h3>你会掌握</h3><div class="task-knowledge"><span v-for="k in card.knowledge" :key="k">{{k}}</span></div><h3>操作与数据使用要点</h3><ul class="task-safety"><li v-for="s in card.safety" :key="s">{{s}}</li></ul><div class="task-resources"><h3>关联学习资源</h3><a v-for="r in card.resources" :key="r.url" :href="r.url" :target="r.url.startsWith('http')?'_blank':undefined" rel="noopener noreferrer"><Icon name="BookOpen" :size="17"/>{{r.title}}<Icon name="ArrowUpRight" :size="16"/></a></div><RouterLink :to="'/skills/'+card.ability_id" class="btn green full">进入对应训练<Icon name="ArrowRight" :size="18"/></RouterLink></template><div v-else class="task-empty"><div class="task-empty-icon"><Icon name="FileCheck2" :size="59"/></div><h2>一份任务，一条清晰的学习路径。</h2><p>输入企业任务后，你会得到：</p><div><span><Icon name="Check"/>具体的工作情境</span><span><Icon name="Check"/>可操作的学习步骤</span><span><Icon name="Check"/>对应的知识与技能</span><span><Icon name="Check"/>直达训练的学习资源</span></div></div></section></div></div></template>
